<script setup lang="ts">
const {feedbackTarget,captureAction}=useActionFeedback()
const props=defineProps<{game:any;mode:string;regionId?:string}>(),emit=defineEmits(['changed','processing','clear-region','open-world'])
const navigationNews=useNavigationNews()
const data=ref<any>({contracts:[],missions:[],decisions:[]}),people=ref<any>({operators:[],squads:[]}),busy=ref(false),error=ref(''),notice=ref(''),filter=ref(''),selectedContract=ref<any>(null),selectedMission=ref<any>(null),reports=ref<any[]>([]),preview=ref<any>(null),withdrawal=ref<any>(null)
const operationSection=ref('missions'),planError=ref('')
const visibleMissions=computed(()=>data.value.missions.filter((m:any)=>operationSection.value==='history'?!['active','awaiting_decision','returning'].includes(m.status):['active','awaiting_decision','returning'].includes(m.status)))
const statusFilter=ref('actionable'),search=ref('')
const intelContract=ref<any>(null),departure=ref<any>(null)
const equipmentIds=ref<string[]>([])
const equipmentNames:any={combat:'Combate',recon:'Reconhecimento',medical:'Médico',technical:'Técnico',communication:'Comunicação',logistics:'Logístico'}
const squadId=ref(''),members=ref<string[]>([]),reinforcements=ref<string[]>([]),leader=ref(''),deputy=ref(''),posture=ref('balanced'),priority=ref('team_safety'),risk=ref('medium'),policy=ref('normal')
const pendingStore=useState<Record<string,any>>('operation-commands',()=>({}))
const pending=computed({get:()=>pendingStore.value[props.game.id]??null,set:(value:any)=>{pendingStore.value={...pendingStore.value,[props.game.id]:value}}})
const locked=computed(()=>busy.value||!!pending.value),base=()=>'/api/v1/games/'+props.game.id
const money=(n:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(n/100)
const statusNames:any={rival_active:'Em execução por rival',rival_completed:'Concluído por rival',rival_failed:'Rival fracassou',available:'Disponível',accepted:'Aceito',active:'Em execução',awaiting_decision:'Aguardando decisão',returning:'Retornando',completed:'Concluído',failed:'Fracassado',expired:'Expirado',cancelled:'Cancelado',withdrawn:'Retirada concluída'}
const typeNames:any={security:'Segurança',escort:'Escolta',reconnaissance:'Reconhecimento',extraction:'Extração',recovery:'Recuperação',rescue:'Resgate'}
const outcomeNames:any={success:'Sucesso',partial:'Parcial',delay:'Atraso',failure:'Falha',complication:'Complicação',completed:'Concluída',failed:'Fracassada',withdrawn:'Retirada',decision:'Decisão solicitada'}
const contracts=computed(()=>data.value.contracts.filter((c:any)=>(!filter.value||c.type===filter.value)&&(!props.regionId||c.regionId===props.regionId)&&(statusFilter.value==='all'||statusFilter.value==='actionable'?statusFilter.value==='all'||['available','accepted'].includes(c.status):c.status===statusFilter.value)&&(!search.value||[c.title,c.regionName,c.countryName,c.clientName].join(' ').toLocaleLowerCase('pt-BR').includes(search.value.toLocaleLowerCase('pt-BR')))))
const permanentOptions=computed(()=>people.value.operators.filter((o:any)=>people.value.squads.find((s:any)=>s.id===squadId.value)?.memberIds.includes(o.id)))
const scheduled=(target:string,kind?:string)=>(data.value.pendingOrders??[]).filter((o:any)=>o.target===target&&(!kind||o.kind===kind))
const name=(id:string)=>people.value.operators.find((o:any)=>o.id===id)?.name||id
async function refresh(){try{const [ops,staff]=await Promise.all([$fetch(base()+'/operations'),$fetch(base()+'/personnel')]);data.value=ops;people.value=staff;navigationNews.markRead(props.game.id,props.mode==='contracts'?'contracts':'operations.'+operationSection.value);return true}catch(e:any){error.value=e.data?.message||'Não foi possível carregar as operações.';return false}}
async function run(path:string,body:any={}){
 if(busy.value)return
 const command=pending.value||{path,body:{...body,requestId:crypto.randomUUID(),expectedVersion:body.expectedVersion??data.value.stateVersion}}
 pending.value=command;busy.value=true;emit('processing',true);error.value='';let done=false
 try{const response=await $fetch<any>(base()+command.path,{method:'POST',body:command.body});if(!await refresh())return;pending.value=null;preview.value=null;selectedContract.value=null;withdrawal.value=null;notice.value=response.cancelledOrderId?'Ordem removida. A ação não será confirmada.':'Ordem agendada. Confirme ao passar o turno ou remova neste card.';done=true}
 catch(e:any){if(e.status>=400&&e.status<500){pending.value=null;preview.value=null;await refresh()}error.value=e.data?.message||'Falha de conexão. Repetir usará o mesmo comando.'}
 finally{busy.value=false;emit('processing',!!pending.value)}
 if(done)emit('changed')
}
function chooseSquad(){const s=people.value.squads.find((s:any)=>s.id===squadId.value);members.value=[...(s?.memberIds??[])];reinforcements.value=[];leader.value=s?.effectiveLeaderId||s?.leaderId||'';deputy.value=s?.deputyId===leader.value?'':s?.deputyId||'';posture.value=s?.directives.posture||'balanced';priority.value=s?.directives.priority||'team_safety';risk.value=s?.directives.riskTolerance||'medium';policy.value=s?.directives.withdrawalPolicy||'normal';preview.value=null}
function plan(c:any){planError.value='';equipmentIds.value=[];selectedContract.value=c;preview.value=null;squadId.value=people.value.squads[0]?.id||'';chooseSquad()}
function planBody(){return {equipmentIds:equipmentIds.value,squadId:squadId.value,memberIds:members.value,reinforcementIds:reinforcements.value,leaderId:leader.value||undefined,deputyId:deputy.value||null,directives:{posture:posture.value,priority:priority.value,riskTolerance:risk.value,withdrawalPolicy:policy.value}}}
async function review(){if(locked.value)return;busy.value=true;emit('processing',true);error.value='';planError.value='';preview.value=null;try{const body=planBody();preview.value={...await $fetch<any>(base()+'/contracts/'+selectedContract.value.id+'/plan',{method:'POST',body}),body}}catch(e:any){planError.value=e.data?.message||'Formação inválida.'}finally{busy.value=false;emit('processing',false)}}
async function details(m:any){selectedMission.value=m;reports.value=[];departure.value=null;try{const detail=await $fetch<any>(base()+'/missions/'+m.id);departure.value=detail.intelligenceAtDeparture}catch{error.value='Não foi possível carregar o snapshot da missão.'}try{reports.value=await $fetch<any[]>(base()+'/missions/'+m.id+'/reports?limit=100')}catch{error.value='Não foi possível carregar os relatórios.'}}
watch(operationSection,()=>{selectedMission.value=null;withdrawal.value=null})
watch(()=>[props.game.id,props.game.stateVersion],async()=>{preview.value=null;selectedMission.value=null;await refresh()})
onMounted(async()=>{emit('processing',!!pending.value);await refresh()})

watch([operationSection,()=>props.mode],()=>{if(data.value?.stateVersion!==undefined)navigationNews.markRead(props.game.id,props.mode==='contracts'?'contracts':'operations.'+operationSection.value)})
</script>
<template>
<div class="operations-panel" @click.capture="captureAction($event)">
 <ActionFeedback :target="feedbackTarget" :error="error" :notice="notice" />
 <section v-if="pending&&!busy" class="panel"><p>Comando aguardando confirmação. A repetição não duplica efeitos.</p><button class="primary" @click="run(pending.path,pending.body)">Repetir comando</button></section>
 <div class="personnel-summary"><span>{{data.missions.filter((m:any)=>['active','awaiting_decision','returning'].includes(m.status)).length}} / {{data.capacity||1}} operações simultâneas</span><span>{{data.decisions.length}} decisões pendentes</span></div>
 <SectionNav :game-id="game.id" scope="operations" v-if="mode==='operations'" v-model="operationSection" label="Seções de operações" :disabled="locked" :items="[['missions','Em andamento'],['decisions','Decisões ('+data.decisions.length+')'],['history','Histórico']]" />
 <p v-if="mode==='contracts'&&data.decisions.length" class="batch-result">{{data.decisions.length}} decisão(ões) pendente(s). Consulte Operações → Decisões.</p>
 <template v-if="mode==='operations'&&operationSection==='decisions'"><p v-if="!data.decisions.length" class="empty">Nenhuma decisão pendente.</p><section v-for="d in data.decisions" :key="d.id" data-action-card :id="'operations-d-'+d.id" class="panel decision-card"><span class="eyebrow">DECISÃO DO COMANDANTE</span><h2>Autorizar a próxima etapa?</h2><p>A equipe reportou uma situação excepcional. Prazo: turno {{d.expiresTurn}}. Sem resposta: {{d.fallbackAction==='withdraw'?'retirada':'abordagem cautelosa'}}. O tempo pode avançar e aplicar essa política.</p><PendingOrderNotice :orders="scheduled(d.id)" :disabled="locked" @remove="run('/orders/'+$event+'/cancel')" /><div v-for="o in d.options" :key="o.id" class="decision-option"><p><strong>{{o.label}}</strong><br>{{o.consequence}}</p><button class="secondary" :disabled="locked||!!scheduled(d.id).length" @click="run('/decisions/'+d.id+'/resolve',{choice:o.id})">{{o.label}}</button></div></section>
 </template><template v-if="mode==='contracts'">
  <div class="section-intro"><h2>Contratos e demandas emergentes</h2><p>Estimativas do contratante podem estar incorretas. Aceitar não reserva operadores nem movimenta o caixa.</p><p>{{data.logisticsNote}}</p></div>
  <p v-if="regionId">Filtro regional: {{data.contracts.find((c:any)=>c.regionId===regionId)?.regionName||'região selecionada'}} <button class="secondary" @click="emit('clear-region')">Ver todas as regiões</button></p>

  <div class="contract-filters"><label class="personnel-label">Buscar contrato ou região<input v-model="search" type="search" placeholder="Nome, local ou contratante"></label><label class="personnel-label">Filtrar situação<select v-model="statusFilter"><option value="actionable">Disponíveis e aceitos</option><option value="all">Todas as situações</option><option value="available">Disponíveis</option><option value="accepted">Aceitos</option><option value="active">Missões da companhia</option><option value="rival_active">Em execução por rival</option></select></label><label class="personnel-label">Filtrar tipo<select v-model="filter"><option value="">Todos os tipos</option><option v-for="(label,key) in typeNames" :key="key" :value="key">{{label}}</option></select></label></div><p>{{contracts.length}} contrato(s) neste filtro.</p>

  <p v-if="!contracts.length" class="empty">Nenhuma oferta para este filtro. Novos contratos chegam no fechamento semanal.</p>
  <div class="personnel-grid"><article v-for="c in contracts" :key="c.id" data-action-card :id="'operations-c-'+c.id" class="panel operator-card"><span class="eyebrow">{{typeNames[c.type]}} · {{scheduled(c.id).length?'Ação agendada':statusNames[c.status]}}</span><h3>{{c.title}}</h3><details v-if="c.briefing" class="contract-briefing"><summary>Briefing e objetivo</summary><p>{{c.briefing}}</p><p v-if="c.context">{{c.context}}</p></details><p>{{c.countryName}} · {{c.regionName}} · vence T{{c.expiresTurn}}</p><p>Dificuldade estimada {{c.estimatedDifficulty.min}}–{{c.estimatedDifficulty.max}}<br>Risco estimado {{c.estimatedRisk.min}}–{{c.estimatedRisk.max}}<br>{{c.source==='commercial'?'Oferta comercial':'Demanda emergente'}} · {{c.clientName}}</p><p v-if="c.requiredEquipment.length">Equipamento obrigatório: {{c.requiredEquipment.map((id:string)=>equipmentNames[id]).join(', ')}}</p><p>Fonte: {{c.confidence+'% de confiança · '+c.intelSource}}<br>Remuneração máxima: {{money(c.rewardCents)}}<br>Adiantamento: {{money(c.advanceCents)}}<br>Mínimo: {{c.minimumOperators}} operadores</p><div class="personnel-actions"><button class="secondary" @click="intelContract=c">Inteligência e análises</button><button v-if="c.originEventId" class="secondary" @click="emit('open-world',{regionId:c.regionId,eventId:c.originEventId})">Consultar notícia de origem</button><button v-if="c.status==='available'" class="primary" :disabled="locked||!!scheduled(c.id).length" @click="run('/contracts/'+c.id+'/accept')">{{scheduled(c.id,'accept').length?'Aceite agendado':'Aceitar contrato'}}</button><template v-if="c.status==='accepted'&&!scheduled(c.id).length"><button class="primary" :disabled="locked" @click="plan(c)">Planejar missão</button><button class="secondary" :disabled="locked" @click="run('/contracts/'+c.id+'/cancel')">Cancelar aceite · sem custo</button></template></div>  <PendingOrderNotice :orders="scheduled(c.id)" :disabled="locked" @remove="run('/orders/'+$event+'/cancel')" /><section v-if="intelContract?.id===c.id" v-context-panel class="inline-action"><button class="secondary" @click="intelContract=null">Fechar inteligência</button><h2>{{intelContract.title}}</h2><IntelligencePanel :key="game.id+':'+intelContract.id" :game="game" target-type="contract" :target-id="intelContract.id" @changed="emit('changed')" @processing="emit('processing',$event)" /></section>  <section v-if="selectedContract?.id===c.id" v-context-panel class="inline-action mission-planner"><h2>Planejar: {{selectedContract.title}}</h2><form @submit.prevent="review" @change="preview=null;planError=''">
   <label class="personnel-label">Equipe permanente<select v-model="squadId" :disabled="locked" required @change="chooseSquad"><option value="">Selecione</option><option v-for="s in people.squads" :key="s.id" :value="s.id">{{s.name}}</option></select></label>
   <fieldset :disabled="locked"><legend>Permanentes enviados (2 a 6)</legend><label v-for="o in permanentOptions" :key="o.id" class="member-check"><input v-model="members" type="checkbox" :value="o.id" :disabled="o.availability!=='available'">{{o.name}} · {{o.availability==='available'?'Disponível':'Indisponível'}}</label></fieldset>
   <fieldset :disabled="locked"><legend>Reforços temporários (até 2)</legend><label v-for="o in people.operators.filter((o:any)=>!members.includes(o.id)&&o.employment)" :key="o.id" class="member-check"><input v-model="reinforcements" type="checkbox" :value="o.id" :disabled="o.availability!=='available'||(!reinforcements.includes(o.id)&&reinforcements.length>=2)">{{o.name}}</label><p>Vínculos com equipes permanentes serão preservados.</p></fieldset>
   <label class="personnel-label">Líder presente<select v-model="leader" :disabled="locked"><option value="">Selecionar líder</option><option v-for="id in [...members,...reinforcements]" :key="id" :value="id">{{name(id)}}</option></select></label>
   <label class="personnel-label">Substituto<select v-model="deputy" :disabled="locked"><option value="">Sem substituto</option><option v-for="id in [...members,...reinforcements].filter(id=>id!==leader)" :key="id" :value="id">{{name(id)}}</option></select></label>
   <fieldset v-if="data.logistics" :disabled="locked"><legend>Kits da missão</legend><p>Obrigatórios: {{selectedContract.requiredEquipment.map((id:string)=>equipmentNames[id]).join(', ')||'nenhum'}}. A prévia não reserva estoque.</p><label v-for="k in data.logistics.inventory.filter((k:any)=>k.ready)" :key="k.id" class="member-check"><input v-model="equipmentIds" type="checkbox" :value="k.id">{{k.name}} · condição {{k.condition}} · suprimentos {{k.supplies}} · carga {{k.weight}}</label><p v-if="!data.logistics.inventory.some((k:any)=>k.ready)">Nenhum kit apto. Compre e prepare em Visão geral → Sede e logística.</p></fieldset>
   <div class="planning-directives"><label class="personnel-label">Postura<select v-model="posture" :disabled="locked"><option value="cautious">Cautelosa</option><option value="balanced">Equilibrada</option><option value="aggressive">Agressiva</option></select></label><label class="personnel-label">Prioridade<select v-model="priority" :disabled="locked"><option value="objective">Objetivo</option><option value="team_safety">Segurança da equipe</option><option value="deadline">Prazo</option></select></label><label class="personnel-label">Tolerância a risco<select v-model="risk" :disabled="locked"><option value="low">Baixa</option><option value="medium">Média</option><option value="high">Alta</option></select></label><label class="personnel-label">Política de retirada<select v-model="policy" :disabled="locked"><option value="conservative">Conservadora</option><option value="normal">Normal</option><option value="persistent">Persistente</option></select></label></div>
   <div class="personnel-actions"><p v-if="planError" class="error plan-validation" role="alert">{{planError}}</p><button class="primary" :disabled="locked">Validar formação e custos</button><button class="secondary" type="button" :disabled="locked" @click="selectedContract=null">Fechar planejamento</button></div>
  </form><div v-if="preview" class="plan-review"><h3>Revisão de início</h3><p v-if="preview.intelligenceAdvice">{{preview.intelligenceAdvice}}</p><p>{{preview.operatorIds.map(name).join(', ')}}</p><p>Mobilização: {{money(preview.mobilizationCents)}}<br>Adiantamento: {{money(preview.advanceCents)}}<br>Saldo previsto: {{money(preview.cashAfterCents)}}<br>Reserva máxima inicial: {{preview.maxTurns}} turnos.<br>Carga dos kits: {{preview.load}} / {{preview.loadCapacity}}.</p><p>Falha ou retirada devolve o adiantamento e mantém a despesa de mobilização. Condições e reputação podem mudar. Kits selecionados ficam indisponíveis até o retorno; desgaste e consumo não geram débito adicional.</p><button class="primary" :disabled="locked" @click="run('/contracts/'+selectedContract.id+'/start',{...preview.body,expectedVersion:preview.stateVersion})">Agendar início da missão</button></div></section></article></div>
 </template>
 <template v-else-if="operationSection!=='decisions'">
  <div class="section-intro"><h2>{{operationSection==='history'?'Histórico de operações':'Operações em andamento'}}</h2><p>Missões avançam por etapas quando você avança o tempo. Formação e diretrizes enviadas permanecem preservadas.</p></div>


  <p v-if="!visibleMissions.length" class="empty">{{operationSection==='history'?'Nenhuma operação encerrada.':'Nenhuma operação em andamento. Aceite e planeje uma oferta em Contratos.'}}</p><div class="personnel-grid"><article v-for="m in visibleMissions" :key="m.id" data-action-card :id="'operations-m-'+m.id" class="panel operator-card"><span class="eyebrow">{{statusNames[m.status]}}</span><h3>{{m.contractTitle||data.contracts.find((c:any)=>c.id===m.contractId)?.title||'Missão registrada'}}</h3><p>{{m.completedStages}} / {{m.totalStages}} etapas concluídas<br>Etapa: {{m.stageName}}<br>Início T{{m.startedTurn}}<span v-if="m.endedTurn!==null"> · término T{{m.endedTurn}}</span></p><ul><li v-for="a in m.crew" :key="a.operatorId">{{a.name}} · {{a.assignmentType==='reinforcement'?'reforço':'permanente'}}<span v-if="a.operatorId===m.leaderId"> · líder</span></li></ul><div class="personnel-actions"><button class="secondary" @click="details(m)">Abrir relatórios</button><button v-if="['active','awaiting_decision'].includes(m.status)" class="secondary" :disabled="locked||!!scheduled(m.id).length" @click="withdrawal=m">Solicitar retirada</button></div>  <PendingOrderNotice :orders="scheduled(m.id)" :disabled="locked" @remove="run('/orders/'+$event+'/cancel')" /><section v-if="withdrawal?.id===m.id" v-context-panel class="inline-action decision-card"><h3>Solicitar retirada?</h3><p>Retorno em um turno. Devolução de {{money(withdrawal.advanceCents)}} de adiantamento, custo de mobilização mantido e redução de reputação.</p><div class="personnel-actions"><button class="primary" :disabled="locked" @click="run('/missions/'+withdrawal.id+'/withdraw')">Agendar retirada</button><button class="secondary" :disabled="locked" @click="withdrawal=null">Manter missão</button></div></section>  <section v-if="selectedMission?.id===m.id" v-context-panel class="inline-action mission-reports"><button class="secondary" @click="selectedMission=null">Fechar relatórios</button><h2>Relatórios da missão</h2><details v-if="departure"><summary>Conhecimento registrado na partida · T{{departure.collectedTurn}}</summary><p v-for="t in departure.contract.topics" :key="t.topic">{{t.topic==='risk'?'Risco':'Dificuldade'}} · {{t.estimate?t.estimate.min+'–'+t.estimate.max:'desconhecido'}} · confiança {{t.confidence}}% · coleta T{{t.collectedTurn}} · validade T{{t.validUntilTurn}}</p><p>Snapshot preservado; novas informações podem orientar a equipe durante a operação.</p></details><p v-if="!reports.length">Aguardando a primeira etapa.</p><article v-for="r in reports" :key="r.id" class="mission-report"><span class="eyebrow">T{{r.turn}} · {{outcomeNames[r.outcome]}}</span><h3>{{r.title}}</h3><p>{{r.description}}</p><p v-for="k in r.equipment||[]" :key="k.id">Kit {{k.name}} · condição {{k.condition}} · suprimentos {{k.supplies}}</p><p v-for="o in r.conditions||[]" :key="o.operatorId">{{o.name}} · saúde {{o.health}} · fadiga {{o.fatigue}} · moral {{o.morale}}</p><p v-if="r.intelligence">Inteligência usada na avaliação: nível {{r.intelligence.level}}<span v-if="r.intelligence.stale"> · desatualizada</span><span v-if="r.intelligence.conflicting"> · fontes conflitantes</span>.</p><p v-if="r.paymentCents!==undefined">Acerto: {{money(r.paymentCents)}} · reputação {{r.reputationDelta>0?'+':''}}{{r.reputationDelta}}</p></article></section></article></div>
 </template>
</div>
</template>
